import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useParams } from "react-router-dom";

const EmployeeForm = () => {
  const [employee, setEmployee] = useState({
    name: "",
    lastname: "",
    email: "",
    position: "",
  });
  const navigate = useNavigate();
  const { id } = useParams();

  useEffect(() => {
    if (id) {
      axios
        .get(`http://localhost:8080/api/employees/${id}`)
        .then((res) => setEmployee(res.data));
    }
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (id)
      await axios.put(`http://localhost:8080/api/employees/${id}`, employee);
    else await axios.post("http://localhost:8080/api/employees", employee);
    navigate("/");
  };

  return (
    <div className="container mt-3">
      <h2 className="card text-center mt-2 bg-light p-2 ">Add New Employee</h2>
      <form onSubmit={handleSubmit}>
        <div className="mt-3 card bg-light mb-2">
          <div className="d-flex justify-content-center gap-3 mt-2">
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Name"
              value={employee.name}
              onChange={(e) =>
                setEmployee({ ...employee, name: e.target.value })
              }
            />
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Last Name"
              value={employee.lastname}
              onChange={(e) =>
                setEmployee({ ...employee, lastname: e.target.value })
              }
            />
          </div>
          <div className="d-flex justify-content-center gap-3 mt-3">
            <input
              className="form-control rounded w-100 p-2"
              type="email"
              placeholder="Email"
              value={employee.email}
              onChange={(e) =>
                setEmployee({ ...employee, email: e.target.value })
              }
            />
            <input
              className="form-control rounded w-100 p-2"
              type="text"
              placeholder="Position"
              value={employee.position}
              onChange={(e) =>
                setEmployee({ ...employee, position: e.target.value })
              }
            />
          </div>
        </div>
        <div className="mt-2 text-end mt-3">
          <button type="submit" className="rounded btn btn-primary">
            Save
          </button>
        </div>
      </form>
    </div>
  );
};

export default EmployeeForm;
